    let calls = 0
    const started = gate()
    const finish = gate()
    const refresher = createTokenRefresher({
      refresh: async () => {
        calls++
        started.open()
        await finish.opened
        return { accessToken: 'at-solo', refreshToken: 'rt-solo', expiresIn: 3600 }
      },
