  2	 * El access token de una conexión, refrescado una sola vez aunque lo pidan
  3	 * varios a la vez. Con conexión, los que llegan mientras hay un refresco en
  4	 * curso lo comparten aunque cada uno haya cargado un refresh token distinto;
  5	 * sin ella, se comparte por refresh token. Cada refresco pasa por el carril
  6	 * de su familia; antes de presentar un token se comprueba que no se haya
  7	 * rotado ya y que la fila guardada no tenga uno más nuevo. El guardado ocurre
  8	 * dentro de la misma ventana, antes de que nadie más vea el resultado, y no
  9	 * pisa una fila que otro escritor ya rotó.
 10	 *
 11	 * Porte de `getAccessToken`, `_getAccessTokenWithStalenessCheck`,
 12	 * `_refreshWithFreshCredentials`, `getAllAccessTokens` y
 13	 * `getConnectionRefreshMutexStatus` de `omniroute: open-sse/services/tokenRefresh.ts` (MIT).
 14	 */
 15	import { randomUUID } from 'node:crypto'
 16	
 17	import type { SharedStateStore } from '@thyrox/shared-state/port.ts'
 18	
 19	import { casGuardShouldSkipPersist } from './casGuard.ts'
 20	import { activePersist, type RefreshPersistFn } from './persistContext.ts'
 21	import type { ProviderRefreshOutcome, RefreshCredentials } from './providerRefreshDispatch.ts'
 22	import type { RefreshLogger } from './refreshErrors.ts'
 23	import { createRefreshSerializer, type RefreshSerializer } from './refreshSerializer.ts'
 24	import { createRotationMap, refreshCacheKey, type RotatedTokens } from './rotationMap.ts'
 25	
 26	/** Una fila guardada vigente al menos este margen se usa tal cual. */
 27	const STORED_TOKEN_MIN_VALIDITY_MS = 60_000
 28	/** El máximo que un dueño puede retener el lease de un refresco compartido. */
 29	const SHARED_LEASE_TTL_MS = 15_000
 30	/** El sondeo de un lease ajeno, cada este tanto, hasta el mismo plazo que su TTL. */
 31	const SHARED_LEASE_POLL_INTERVAL_MS = 25
 32	
 33	export interface StoredConnectionTokens {
 34	  refreshToken?: string | null
 35	  accessToken?: string | null
 36	  expiresAt?: string | null
 37	}
 38	
 39	export interface AccessTokenCredentials extends RefreshCredentials {
 40	  accessToken?: string
 41	}
 42	
 43	export interface TokenRefresherDeps {
 44	  refresh: (provider: string, credentials: RefreshCredentials) => Promise<ProviderRefreshOutcome>
 45	  serialize?: RefreshSerializer
 46	  rotations?: ReturnType<typeof createRotationMap>
 47	  /** La fila guardada de una conexión, descifrada. */
 48	  readConnection?: (connectionId: string) => StoredConnectionTokens | null | undefined | Promise<StoredConnectionTokens | null | undefined>
 49	  now?: () => number
 50	  log?: RefreshLogger
 51	  /** El estado compartido en caliente entre proxies (ADR-THYROX-006). Sin él, sólo coordina el mutex en proceso. */
 52	  sharedState?: SharedStateStore
 53	  /** El id de esta instancia como dueño de un lease. Por defecto, uno aleatorio por proceso. */
 54	  leaseOwner?: string
 55	}
 56	
 57	export interface ConnectionTokenSource {
 58	  provider?: string
 59	  refreshToken?: string
 60	  isActive?: boolean
 61	}
 62	
 63	const hasAccessToken = (result: ProviderRefreshOutcome | StoredConnectionTokens): result is Record<string, unknown> & { accessToken: string } => Boolean(result && 'accessToken' in result && result.accessToken)
 64	const errorMessage = (error: unknown) => (error instanceof Error ? error.message : String(error))
 65	
 66	export function createTokenRefresher(deps: TokenRefresherDeps) {
 67	  const serialize = deps.serialize ?? createRefreshSerializer()
 68	  const rotations = deps.rotations ?? createRotationMap({ now: deps.now })
 69	  const now = deps.now ?? Date.now
 70	  const { log, sharedState } = deps
 71	  const leaseOwner = deps.leaseOwner ?? randomUUID()
 72	  const connectionMutex = new Map<string, { promise: Promise<ProviderRefreshOutcome>; waiters: number }>()
 73	  const inFlightByToken = new Map<string, Promise<ProviderRefreshOutcome>>()
 74	
 75	  const leaseKeyFor = (connectionId: string) => `token-refresh:${connectionId}`
 76	  const sleep = (ms: number) => new Promise<void>(resolve => setTimeout(resolve, ms))
 77	
 78	  /** El token que el dueño del lease ya persistió, leído por la fuente de la conexión. */
 79	  async function readPersistedTokens(connectionId: string): Promise<ProviderRefreshOutcome> {
 80	    if (!deps.readConnection) return null
 81	    const stored = await deps.readConnection(connectionId)
 82	    if (!hasAccessToken(stored ?? {})) return null
 83	    return { accessToken: stored!.accessToken as string, refreshToken: stored!.refreshToken ?? undefined, expiresAt: stored!.expiresAt ?? undefined }
 84	  }
 85	
 86	  /**
 87	   * Sondea el lease ajeno hasta que se libere o venza el plazo. Comprobar que
 88	   * está libre es tomarlo por un instante (TTL 0) y soltarlo enseguida: el
 89	   * puerto no expone una lectura sin efecto, y esta es la única forma de
 90	   * preguntar sin arriesgar un segundo refresco.
 91	   */
 92	  async function waitForPeerRefresh(store: SharedStateStore, connectionId: string): Promise<ProviderRefreshOutcome> {
 93	    const key = leaseKeyFor(connectionId)
 94	    const deadlineAt = now() + SHARED_LEASE_TTL_MS
 95	    let released = false
 96	    while (now() < deadlineAt) {
 97	      if (await store.acquireLease(key, leaseOwner, 0)) {
 98	        await store.releaseLease(key, leaseOwner)
 99	        released = true
100	        break
101	      }
102	      await sleep(SHARED_LEASE_POLL_INTERVAL_MS)
103	    }
104	    if (!released) {
105	      log?.warn?.('TOKEN_REFRESH', `Timed out waiting for the shared token-refresh lease on ${connectionId}`)
106	      return null
107	    }
108	    return readPersistedTokens(connectionId)
109	  }
110	
111	  /** Con `sharedState`, sólo el dueño del lease refresca; sin él, la conducta de siempre. */
112	  async function refreshUnderLease(provider: string, credentials: AccessTokenCredentials, persist: RefreshPersistFn | undefined, connectionId: string): Promise<ProviderRefreshOutcome> {
113	    if (!sharedState) return refreshInLane(provider, credentials).then(result => persistResult(result, persist, `onPersist callback failed for ${provider}/${connectionId}`))
114	    const key = leaseKeyFor(connectionId)
115	    if (!(await sharedState.acquireLease(key, leaseOwner, SHARED_LEASE_TTL_MS))) return waitForPeerRefresh(sharedState, connectionId)
116	    try {
117	      const result = await refreshInLane(provider, credentials)
118	      return await persistResult(result, persist, `onPersist callback failed for ${provider}/${connectionId}`)
119	    } finally {
120	      await sharedState.releaseLease(key, leaseOwner)
121	    }
122	  }
