124	  /** La fila guardada gana si tiene otro refresh token: vigente, se usa; por caducar, es la que se refresca. */
125	  async function refreshWithFreshCredentials(provider: string, credentials: AccessTokenCredentials): Promise<ProviderRefreshOutcome> {
126	    const rotated = rotations.lookup(provider, credentials.refreshToken)
127	    if (rotated) {
128	      log?.info?.('TOKEN_REFRESH', `Rotation map hit for ${provider}. Returning cached rotated tokens (avoids family-revoke).`)
129	      return rotated.result as ProviderRefreshOutcome
130	    }
131	    let current = credentials
132	    if (credentials.connectionId && deps.readConnection) {
133	      try {
134	        const stored = await deps.readConnection(credentials.connectionId)
135	        if (stored?.refreshToken && stored.refreshToken !== credentials.refreshToken) {
136	          log?.info?.('TOKEN_REFRESH', `Stale token detected in memory for ${provider}. Using refreshed token from DB.`)
137	          const storedExpiresAt = stored.expiresAt ? new Date(stored.expiresAt).getTime() : 0
138	          if (storedExpiresAt > now() + STORED_TOKEN_MIN_VALIDITY_MS) {
139	            log?.info?.('TOKEN_REFRESH', 'DB token is still valid. Skipping OAuth refresh.')
140	            return { accessToken: stored.accessToken as string, refreshToken: stored.refreshToken, expiresAt: stored.expiresAt }
141	          }
142	          current = { ...credentials, refreshToken: stored.refreshToken, accessToken: stored.accessToken ?? undefined }
143	        }
144	      } catch (error) {
145	        log?.warn?.('TOKEN_REFRESH', `Failed to check DB for stale token: ${errorMessage(error)}`)
146	      }
147	    }
148	    const result = await deps.refresh(provider, current)
149	    if (hasAccessToken(result) && result.refreshToken && !('error' in result)) rotations.record(provider, current.refreshToken, result as unknown as RotatedTokens)
150	    return result
151	  }
152	
153	  /** El refresco en el carril de su familia: la comprobación de frescura va dentro, justo antes de la red. */
154	  const refreshInLane = (provider: string, credentials: AccessTokenCredentials) => serialize(provider, () => refreshWithFreshCredentials(provider, credentials))
155	
156	  async function persistResult(result: ProviderRefreshOutcome, persist: RefreshPersistFn | undefined, failureContext: string): Promise<ProviderRefreshOutcome> {
157	    if (!hasAccessToken(result) || !persist) return result
158	    if (await casGuardShouldSkipPersist(log)) return result
159	    try {
160	      await persist(result)
161	    } catch (error) {
162	      log?.error?.('TOKEN_REFRESH', `${failureContext}: ${errorMessage(error)}`)
163	      throw error
164	    }
165	    return result
166	  }
