168	  async function getAccessToken(provider: string, credentials: AccessTokenCredentials | null | undefined, persist?: RefreshPersistFn): Promise<ProviderRefreshOutcome> {
169	    if (!credentials || typeof credentials.refreshToken !== 'string' || !credentials.refreshToken) {
170	      log?.warn?.('TOKEN_REFRESH', `No valid refresh token available for provider: ${provider}`)
171	      return null
172	    }
173	    const effectivePersist = persist ?? activePersist()
174	    const { connectionId } = credentials
175	
176	    if (connectionId && typeof connectionId === 'string') {
177	      const existing = connectionMutex.get(connectionId)
178	      if (existing) {
179	        existing.waiters++
180	        log?.info?.('TOKEN_REFRESH', 'Concurrent refresh detected — sharing in-flight refresh', { provider, connectionId, waiters: existing.waiters })
181	        return existing.promise
182	      }
183	      const promise = refreshUnderLease(provider, credentials, effectivePersist, connectionId).finally(() => connectionMutex.delete(connectionId))
184	      connectionMutex.set(connectionId, { promise, waiters: 0 })
185	      return promise
186	    }
187	
188	    const cacheKey = refreshCacheKey(provider, credentials.refreshToken)
189	    const inFlight = inFlightByToken.get(cacheKey)
190	    if (inFlight) {
191	      log?.info?.('TOKEN_REFRESH', `Reusing in-flight refresh for ${provider}`)
192	      return inFlight
193	    }
194	    const promise = refreshInLane(provider, credentials)
195	      .then(result => {
196	        if (hasAccessToken(result) && !effectivePersist) {
197	          log?.warn?.('TOKEN_REFRESH', `Layer 2 refresh succeeded for ${provider} without onPersist — DB row will not be updated with rotated token. Callers should pass connectionId for Layer 1 atomicity.`)
198	        }
199	        return persistResult(result, effectivePersist, `Layer 2 onPersist callback failed for ${provider}`)
200	      })
201	      .finally(() => inFlightByToken.delete(cacheKey))
202	    inFlightByToken.set(cacheKey, promise)
203	    return promise
204	  }
