206	  /** El token de cada conexión activa con proveedor, por proveedor. */
207	  async function getAllAccessTokens(connections: readonly ConnectionTokenSource[] | null | undefined): Promise<Record<string, ProviderRefreshOutcome>> {
208	    const results: Record<string, ProviderRefreshOutcome> = {}
209	    for (const connection of connections ?? []) {
210	      if (!connection.isActive || !connection.provider) continue
211	      const token = await getAccessToken(connection.provider, { refreshToken: connection.refreshToken as string })
212	      if (token) results[connection.provider] = token
213	    }
214	    return results
215	  }
216	
217	  function connectionMutexStatus(): Record<string, { waiters: number }> {
218	    return Object.fromEntries([...connectionMutex].map(([connectionId, entry]) => [connectionId, { waiters: entry.waiters }]))
219	  }
220	
221	  return { getAccessToken, getAllAccessTokens, connectionMutexStatus }
222	}
